@Override
    protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity) {
        super.entityInside(state, level, pos, entity);
        if (springelatin) entity.setDeltaMovement(0, 0.55, 0);
        else if (!level.isClientSide && entity instanceof LivingEntity living) living.addEffect(new MobEffectInstance(StatusContent.INFECTED, 100, 1));
    }

@Override
    public void animateTick(BlockState state, Level level, BlockPos pos, RandomSource random) {
        super.animateTick(state, level, pos, random);
        if (!springelatin && random.nextDouble() < 0.01 && level.isEmptyBlock(pos.above()) && level.getBiome(pos).is(GRAVEYARD)) {
            level.addParticle(ParticleTypes.CAMPFIRE_COSY_SMOKE, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 0, 0.1, 0);
        }
    }

@Override
    protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (!stack.is(MaterialContent.items().get("drinking_straw").get()) && !stack.is(MaterialContent.items().get("silly_straw").get())) return ItemInteractionResult.SUCCESS;
        if (!level.isClientSide && level.getBlockState(pos).is(this)) {
            BlockState empty = GeoDecorContent.block(GeoDecorKind.BIG_GLASS_BOTTLE).defaultBlockState().setValue(ANIMATION, state.getValue(ANIMATION));
            if (level.setBlock(pos, empty, 3)) {
                player.getFoodData().eat(5, .6F);
                level.playSound(null, pos, SoundEvents.GENERIC_DRINK, SoundSource.NEUTRAL, 1, 1);
            }
        }
        return ItemInteractionResult.SUCCESS;
    }

@Override
    protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (!stack.is(MaterialContent.items().get("drinking_straw").get()) && !stack.is(MaterialContent.items().get("silly_straw").get())) return ItemInteractionResult.SUCCESS;
        if (!level.isClientSide && level.getBlockState(pos).is(this)) {
            BlockState empty = GeoDecorContent.block(GeoDecorKind.BIG_GLASS_BOTTLE).defaultBlockState().setValue(ANIMATION, state.getValue(ANIMATION));
            if (level.setBlock(pos, empty, 3)) {
                player.getFoodData().eat(5, .6F);
                level.playSound(null, pos, SoundEvents.GENERIC_DRINK, SoundSource.NEUTRAL, 1, 1);
            }
        }
        return ItemInteractionResult.SUCCESS;
    }

@Override
    protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity) {
        super.entityInside(state, level, pos, entity);
        if (!level.isClientSide && entity instanceof LivingEntity living && !entity.getType().is(BLACKLIST)) {
            living.addEffect(new MobEffectInstance(buff, 120, 1, true, true));
        }
    }

@Override
    public void animateTick(BlockState state, Level level, BlockPos pos, RandomSource random) {
        level.addParticle(ParticleTypes.BUBBLE_COLUMN_UP, pos.getX() + random.nextDouble(), pos.getY() + 1.0,
                pos.getZ() + random.nextDouble(), 0, 1, 0);
    }

@Override
    protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos,
            Player player, InteractionHand hand, BlockHitResult hit) {
        ItemStack straw = player.getMainHandItem();
        boolean silly = straw.is(MaterialContent.items().get("silly_straw").get());
        boolean drinking = straw.is(MaterialContent.items().get("drinking_straw").get());
        if ((!silly && !drinking) || player.getCooldowns().isOnCooldown(straw.getItem())) {
            return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;
        }
        if (!level.isClientSide) {
            player.getCooldowns().addCooldown(straw.getItem(), silly ? 60 : 20);
            player.setAirSupply(silly ? 300 : Math.min(300, player.getAirSupply() + 60));
            straw.hurtAndBreak(1, player, EquipmentSlot.MAINHAND);
            level.playSound(null, pos, SoundEvents.HONEY_DRINK, SoundSource.NEUTRAL, 1, 1);
            if (player instanceof ServerPlayer serverPlayer) {
                var advancement = serverPlayer.server.getAdvancements().get(ResourceLocation.fromNamespaceAndPath(ThermalShockReforged.MOD_ID, "breather_sponge_get"));
                if (advancement != null) {
                    var progress = serverPlayer.getAdvancements().getOrStartProgress(advancement);
                    if (!progress.isDone()) for (String criterion : progress.getRemainingCriteria()) serverPlayer.getAdvancements().award(advancement, criterion);
                }
            }
        }
        return ItemInteractionResult.SUCCESS;
    }

@Override protected void onPlace(BlockState state, Level level, BlockPos pos, BlockState previous, boolean moving) {
        super.onPlace(state, level, pos, previous, moving);
        if (!level.isClientSide && !previous.is(this)) level.setBlock(pos, state.setValue(VARIANT, ThreadLocalRandom.current().nextInt(3)), 3);
    }

@Override
    protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block neighbor, BlockPos from, boolean moving) {
        super.neighborChanged(state, level, pos, neighbor, from, moving);
        if (!level.isClientSide) {
            int snowy = level.getBlockState(pos.above()).is(Blocks.SNOW) ? 1 : 0;
            if (state.getValue(BLOCKSTATE) != snowy) level.setBlock(pos, state.setValue(BLOCKSTATE, snowy), 3);
        }
    }

