    }

@Override public void stepOn(Level level, BlockPos pos, BlockState state, Entity entity) {
        super.stepOn(level, pos, state, entity);
        if (!level.isClientSide) entity.hurt(level.damageSources().lightningBolt(), 1);
    }

@Override protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block neighbor, BlockPos from, boolean moving) {
        super.neighborChanged(state, level, pos, neighbor, from, moving);
        if (level instanceof ServerLevel server && level.isEmptyBlock(pos.below()) && level.getBlockState(pos).is(this)
                && level.destroyBlock(pos, false) && !level.getBlockState(pos).is(this)) {
            ItemEntity drop = new ItemEntity(server, pos.getX(), pos.getY(), pos.getZ(), new ItemStack(GrowthContent.SPIRE_BLOOM_RUBICON.get()));
            drop.setPickUpDelay(10);
            server.addFreshEntity(drop);
        }
    }

@Override protected void onPlace(BlockState state, Level level, BlockPos pos, BlockState oldState, boolean moving) {
        super.onPlace(state, level, pos, oldState, moving);
        if (!(level instanceof ServerLevel server) || oldState.is(this) || !level.getBlockState(pos).is(this)) return;
        boolean clear = level.hasChunksAt(pos.getX() - 1, pos.getZ() - 1, pos.getX() + 1, pos.getZ() + 1);
        for (int dx = -1; dx <= 1 && clear; dx++) for (int dz = -1; dz <= 1; dz++) if ((dx != 0 || dz != 0) && !level.isEmptyBlock(pos.offset(dx, 0, dz))) { clear = false; break; }
        if (clear) {
            level.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
            var bug = LiftbugContent.LIFTBUG.get().spawn(server, pos, MobSpawnType.MOB_SUMMONED);
            if (bug != null && server.getEntity(bug.getUUID()) == bug) {
                bug.setDeltaMovement(0, 0, 0);
                server.sendParticles(ParticleTypes.POOF, pos.getX() + .5, pos.getY() + .5, pos.getZ() + .5, 20, .5, .5, .5, 0);
                server.playSound(null, pos, SoundEvents.SNIFFER_EGG_HATCH, SoundSource.NEUTRAL, 1, 1);
                return;
            }
            if (bug != null) bug.discard();
        } else level.destroyBlock(pos, false);
        Block.dropResources(state, server, pos);
        server.playSound(null, pos, SoundEvents.NOTE_BLOCK_BASS.value(), SoundSource.NEUTRAL, 1, 1);
        for (int dx = -2; dx <= 2; dx++) for (int dz = -2; dz <= 2; dz++) server.sendParticles(ParticleTypes.CRIT, pos.getX() + dx + .5, pos.getY() + .5, pos.getZ() + dz + .5, 1, .001, .001, .001, 0);
    }

@Override
    protected void entityInside(BlockState state, Level level, BlockPos pos, Entity entity) {
        super.entityInside(state, level, pos, entity);
        if (!windblown && !entity.isShiftKeyDown() && level instanceof ServerLevel server && level.getBlockState(pos).is(this)
                && server.setBlock(pos, SpecialPlantContent.WINDBLOWN_LOQUE_DANDELION.get().defaultBlockState(), 3)) {
            server.sendParticles(ParticleTypes.POOF, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 5, 0.3, 0.3, 0.3, 0.05);
            server.playSound(null, pos, SoundEvents.WOOL_BREAK, SoundSource.BLOCKS, 1, 0.6F);
        }
    }

@Override
    protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos,
            Player player, InteractionHand hand, BlockHitResult hit) {
        interact(level, pos, player);
        return ItemInteractionResult.SUCCESS;
    }

@Override
    protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hit) {
        interact(level, pos, player);
        return InteractionResult.SUCCESS;
    }

@Override public boolean onDestroyedByPlayer(BlockState state, Level level, BlockPos pos, Player player, boolean harvest, FluidState fluid) {
        boolean result = super.onDestroyedByPlayer(state, level, pos, player, harvest, fluid);
        if (result && !level.getBlockState(pos).is(this) && level instanceof ServerLevel server && server.random.nextDouble() < .2) {
            var drop = new ItemEntity(level, pos.getX() - .5, pos.getY() - .5, pos.getZ() - .5, new ItemStack(lunar ? GrowthContent.LUNALEMON_SEED.get() : GrowthContent.STARFRUIT_SEED.get()));
            drop.setPickUpDelay(10);
            server.addFreshEntity(drop);
        }
        return result;
    }

@Override protected void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
        BlockPos below = pos.below();
        if (level.hasChunkAt(below) && level.getBlockEntity(below) != null) {
            int amount = 150;
            if (level.isDay()) {
                var unsided = level.getCapability(Capabilities.EnergyStorage.BLOCK, below, null);
                if (unsided != null && unsided.canReceive()) amount = 5;
            }
            var receiver = level.getCapability(Capabilities.EnergyStorage.BLOCK, below, Direction.UP);
            if (receiver != null) receiver.receiveEnergy(amount, false);
        }
        level.scheduleTick(pos, this, 1);
    }

@Override protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (level instanceof ServerLevel server) toggle(server, pos, player);
        return ItemInteractionResult.SUCCESS;
    }

@Override protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hit) {
        if (level instanceof ServerLevel server) toggle(server, pos, player);
        return InteractionResult.SUCCESS;
    }

