            level.destroyBlock(position, false);
            level.playSound(null, position, SoundEvents.TURTLE_EGG_CRACK, SoundSource.BLOCKS, 1, 0.5F);
            ModEntities.PONDLER.get().spawn(level, position, MobSpawnType.MOB_SUMMONED);
            return;
